package vn.rtr.aeris.beta01runtime;
import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.function.*;
/** Bounded best-effort measurements, never authority or an alternate durable WAL. */
public final class IoTiming {
 public interface CpuClock{long nowNs();String source();}
 public interface Work{void run()throws Exception;}
 public static final int MAX_BYTES=256*1024,RING=256;private static final ThreadLocal<IoTiming>CURRENT=new ThreadLocal<>();
 public static CpuClock androidCpu(){try{final Method m=Class.forName("android.os.Debug").getMethod("threadCpuTimeNanos");return new CpuClock(){public long nowNs(){try{return((Number)m.invoke(null)).longValue();}catch(Exception e){return-1;}}public String source(){return"android.os.Debug.threadCpuTimeNanos_CURRENT_THREAD";}};}catch(Exception e){return new CpuClock(){public long nowNs(){return-1;}public String source(){return"NOT_AVAILABLE_NON_ANDROID_OR_REFLECTION_FAILED";}};}}
 public static final class Token{final String phase;final long wall,cpu,thread;Token(String p,long w,long c){phase=p;wall=w;cpu=c;thread=Thread.currentThread().getId();}}
 private final LongSupplier wall;private final CpuClock cpu;private final Map<String,Object>context;private final String sourceSHA;private final LinkedHashMap<String,long[]>stats=new LinkedHashMap<>();private final ArrayDeque<Map<String,Object>>spans=new ArrayDeque<>(),queues=new ArrayDeque<>();private long spanCount,queueCount,measurementErrors,maxLoopMessages,cpuUnavailableOperations;private boolean published;
 public IoTiming(LongSupplier wall,CpuClock cpu,Map<String,Object>context,String sourceSHA){this.wall=Objects.requireNonNull(wall);this.cpu=Objects.requireNonNull(cpu);if(context==null||context.size()>16||sourceSHA!=null&&!sourceSHA.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("DIAGNOSTIC_CONTEXT_BOUND");for(Map.Entry<String,Object>e:context.entrySet())if(e.getKey()==null||!e.getKey().matches("[A-Za-z0-9_]{1,32}")||!(e.getValue()instanceof String)||((String)e.getValue()).length()>128)throw new IllegalArgumentException("DIAGNOSTIC_CONTEXT_BOUND");this.context=Collections.unmodifiableMap(new LinkedHashMap<>(context));this.sourceSHA=sourceSHA;}
 public void install(){CURRENT.set(this);}public void uninstall(){CURRENT.remove();}
 public static Token beginCurrent(String phase){IoTiming t=CURRENT.get();return t==null?null:t.begin(phase);}public static void endCurrent(Token token){IoTiming t=CURRENT.get();if(t!=null)t.end(token);}
 public Token begin(String phase){try{if(!phase.matches("[a-zA-Z0-9_.-]{1,48}"))throw new IllegalArgumentException();return new Token(phase,wall.getAsLong(),cpu.nowNs());}catch(Throwable ignored){synchronized(this){measurementErrors++;}return null;}}
 public synchronized void end(Token t){if(t==null)return;try{long end=wall.getAsLong(),c=cpu.nowNs(),w=end-t.wall,used=t.cpu<0||c<0?-1:c-t.cpu;if(w<0||used< -1||Thread.currentThread().getId()!=t.thread){measurementErrors++;return;}long[]s=stats.get(t.phase);if(s==null){if(stats.size()>=32){measurementErrors++;return;}s=new long[14];stats.put(t.phase,s);}s[0]++;s[1]+=w;s[2]=Math.max(s[2],w);if(used>=0){s[3]+=used;s[4]=Math.max(s[4],used);s[13]++;}else cpuUnavailableOperations++;long[]bounds={1000000,5000000,20000000,50000000,100000000,200000000,500000000};int b=0;while(b<bounds.length&&w>bounds[b])b++;s[5+b]++;spanCount++;if(spans.size()==RING)spans.removeFirst();spans.addLast(Values.map("phase",t.phase,"threadId",t.thread,"beginElapsedNs",t.wall,"endElapsedNs",end,"wallNs",w,"threadCpuNs",used));}catch(Throwable ignored){measurementErrors++;}}
 public synchronized void queue(String kind,long serial,long producer,long offered,long consumed,int depth){try{if(kind==null||!kind.matches("[A-Z_]{1,32}"))throw new IllegalArgumentException();queueCount++;if(queues.size()==RING)queues.removeFirst();queues.addLast(Values.map("kind",kind,"threadId",Thread.currentThread().getId(),"queueDwellThreadCPU",null,"queueDwellMeaning","ELAPSED_WALL_ONLY_NO_CROSS_THREAD_CPU_SUBTRACTION","serial",serial,"producerElapsedNs",producer,"offerElapsedNs",offered,"consumeElapsedNs",consumed,"depth",depth));}catch(Throwable ignored){measurementErrors++;}}
 public synchronized void loopMessages(int n){maxLoopMessages=Math.max(maxLoopMessages,n);}
 public void measure(String phase,Work work)throws Exception{Token t=begin(phase);try{work.run();}finally{end(t);}}
 public NativeSegments.Sync wrapSync(final NativeSegments.Sync real){return new NativeSegments.Sync(){public void file(FileDescriptor fd)throws IOException{Token t=begin("journal.fsync");try{real.file(fd);}finally{end(t);}}public void directory(File dir)throws IOException{Token t=begin("journal.dirsync");try{real.directory(dir);}finally{end(t);}}};}
 public synchronized byte[] bytes(String terminal){List<Object>summary=new ArrayList<>();for(Map.Entry<String,long[]>e:stats.entrySet()){long[]s=e.getValue();List<Long>bins=new ArrayList<>();for(int i=5;i<13;i++)bins.add(s[i]);summary.add(Values.map("phase",e.getKey(),"count",s[0],"wallTotalNs",s[1],"wallMaxNs",s[2],"cpuKnownCount",s[13],"cpuTotalKnownNs",s[3],"cpuMaxKnownNs",s[4],"wallHistogram",bins));}byte[]out=Values.bytes(Values.map("format","aeris-native-io-diagnostics","version",1,"context",context,"APKSourceSHA256",sourceSHA,"wallClockDomain","ANDROID_ELAPSED_REALTIME_NS_CALLER_CLOCK","threadCpuClock",cpu.source(),"clockResolution","PLATFORM_REPORTED_NS_PRECISION_NOT_MEASURED_RESOLUTION","nonCPUWallCause","UNKNOWN_NOT_EXCLUSIVE_FILESYSTEM_OR_SCHEDULER","phaseSummary",summary,"spanCount",spanCount,"queueEventCount",queueCount,"recentSpans",new ArrayList<>(spans),"recentQueueEvents",new ArrayList<>(queues),"ringCapacity",RING,"maximumMessagesPerOuterLoop",maxLoopMessages,"measurementErrors",measurementErrors,"cpuUnavailableOperations",cpuUnavailableOperations,"terminalStateSHA256",Values.hash(terminal.getBytes(java.nio.charset.StandardCharsets.UTF_8)),"diagnosticNotAuthorityOrFlightProof",true));if(out.length>MAX_BYTES)throw new IllegalStateException("DIAGNOSTIC256K_BOUND");return out;}
 public synchronized void publish(File files,String run,String terminal,NativeSegments.Sync sync)throws IOException{if(published)throw new IOException("DIAGNOSTIC_SINGLE_PUBLICATION");published=true;byte[]data=bytes(terminal);File root=new File(files,"native-io-diagnostics");if(!root.isDirectory()&&!root.mkdir())throw new IOException("DIAGNOSTIC_DIRECTORY");if(root.getUsableSpace()<NativeSegments.RESERVE+data.length+16384)throw new IOException("DIAGNOSTIC_RESERVE");File pending=new File(root,run+".pending"),dest=new File(root,run+".json");if(pending.exists()||dest.exists()||!pending.createNewFile())throw new IOException("DIAGNOSTIC_EXCLUSIVE");try(FileOutputStream out=new FileOutputStream(pending)){out.write(data);sync.file(out.getFD());}if(!pending.renameTo(dest))throw new IOException("DIAGNOSTIC_RENAME");sync.directory(root);}
}
